/* ================= TRAFFIC RULES =================
   Every road has two lanes: vehicles keep to their own side (LANE from the centre line), so the two
   directions never meet. In the same lane a vehicle slows and stops behind the one in front; at
   junctions it gives way to anything already in its path. If two vehicles wait for each other, the
   one first in the queue goes. */
const LANE=2.1;
function trafficRules(dt){const L=[];for(const k of VEH){if(k.mode==='parked'||!k.g.parent)continue;L.push(k);}
  if(S.car&&myCarG&&myCarG.parent)L.push({g:myCarG,rd:S.car.dir,player:true});
