    for(const o of L){if(o===k)continue;const q=o.g.position,dx=q.x-p.x,dz=q.z-p.z,al=dx*fx+dz*fz;if(al<=0.5||al>11)continue;const lat=Math.abs(dx*fz-dz*fx);
